# Reference verdicts for gaply_core's percent_matches_count (Phase 1, Step 6).
#
# Run with the R that has the reference packages, by its full path:
#
#   /usr/local/bin/Rscript make_percent_count_fixtures.R
#
# Writes percent_count_fixtures.csv next to this script. Columns: count,
# denominator, percent (the printed percentage, trailing zeros kept),
# consistent. `consistent` is TRUE when 100 * count / denominator, rerounded
# by scrutiny::reround to the percentage's printed decimals with rounding =
# "up_or_down", equals the printed percentage: the same closed interval Gaply
# reads, computed by a different route.
#
# The grid: every denominator 1..60 and count 0..denominator; for each, the
# percentage printed with 0 and with 1 decimal, both correctly rounded and one
# unit of its last place below and above. A fixed stride of 7 keeps ~1,600 rows.

suppressPackageStartupMessages(library(scrutiny))

script_dir <- local({
  a <- commandArgs(trailingOnly = FALSE)
  f <- sub("^--file=", "", a[grep("^--file=", a)])
  if (length(f) == 1) dirname(normalizePath(f)) else getwd()
})

rows <- list()
for (den in 1:60) for (count in 0:den) for (d in 0:1) for (shift in -1:1) {
  share <- 100 * count / den
  printed <- round(share * 10^d) / 10^d + shift / 10^d
  if (printed < 0) next
  rows[[length(rows) + 1]] <- data.frame(count = count, denominator = den,
    percent = formatC(printed, format = "f", digits = d), d = d)
}
rows <- do.call(rbind, rows)
rows <- rows[seq(1, nrow(rows), by = 7), ]

rows$consistent <- mapply(function(count, den, percent, d) {
  r <- reround(100 * count / den, digits = d, rounding = "up_or_down")
  any(dplyr::near(r, as.numeric(percent)))
}, rows$count, rows$denominator, rows$percent, rows$d)

out <- file.path(script_dir, "percent_count_fixtures.csv")
con <- file(out, "w")
writeLines(c(
  "# Reference verdicts for gaply_core's percent_matches_count.",
  "# Generated by /usr/local/bin/Rscript make_percent_count_fixtures.R (do not edit by hand).",
  paste0("# ", R.version.string),
  paste0("# scrutiny ", as.character(packageVersion("scrutiny")),
         "; consistent = reround(100 * count / denominator, decimals, up_or_down) == percent"),
  "count,denominator,percent,consistent"
), con)
writeLines(sprintf("%d,%d,%s,%s", rows$count, rows$denominator, rows$percent,
                   ifelse(rows$consistent, "TRUE", "FALSE")), con)
close(con)
cat(sprintf("wrote %d rows to %s\n", nrow(rows), out))
